const b = $json.body ?? $json;
const consultaId = b.consultaId ?? 'consulta-temp';
const pregunta = (b.pregunta ?? b.mensaje ?? '').trim();
const nivelExperiencia = b.nivelExperiencia ?? 'Principiante';
const areaInteres = b.areaInteres ?? 'Desarrollo Web';

// Filtro determinista en Qdrant: solo cursos activos
const filter = {
  must: [
    {
      key: 'estado',
      match: { value: true }
    }
  ]
};

return [{
  json: {
    consultaId,
    pregunta,
    nivelExperiencia,
    areaInteres,
    filter,
    qdrant_url: 'http://qdrant:6333',
    coleccion: 'cursos',
    modelo_embedding: 'text-embedding-3-small',
    limite: 5,
    score_threshold: 0.45
  }
}];

const c = $('Prepara Config & Filtros').first().json;
const r = $input.first().json;
if (!r.data?.length) throw new Error('No se pudo generar embedding en OpenRouter');
return [{
  json: {
    ...c,
    vector: r.data[0].embedding
  }
}];

