const config = $('Prepara Config & Filtros').first().json;
const puntos = $('Buscar en Qdrant').first().json.result ?? [];

const cursos = puntos.map((p, idx) => ({
  posicion: idx + 1,
  cursoId: p.payload?.cursoId ?? p.id,
  nombre: p.payload?.nombre ?? 'Curso',
  descripcion: p.payload?.descripcion ?? '',
  categoriaNombre: p.payload?.categoriaNombre ?? '',
  nivelNombre: p.payload?.nivelNombre ?? '',
  duracion: p.payload?.duracion ?? 0,
  modalidad: p.payload?.modalidad ?? 'Virtual',
  precio: p.payload?.precio ?? 0,
  similitud: Number((p.score ?? 0).toFixed(4))
}));

const contexto = cursos.map((c, idx) => {
  return `Curso #${idx + 1}: ${c.nombre}
- Categoría: ${c.categoriaNombre} | Nivel: ${c.nivelNombre}
- Modalidad: ${c.modalidad} | Duración: ${c.duracion} horas | Precio: $${c.precio} USD
- Similitud semántica con la consulta: ${c.similitud}
- Descripción: ${c.descripcion}`;
}).join('\n\n');

const prompt = `Eres un asesor académico experto de RutaIA.
Tu misión es responder al estudiante con recomendaciones precisas y fundamentadas basadas EXCLUSIVAMENTE en el contexto de cursos recuperados de la institución.

PERFIL DEL ESTUDIANTE:
- Nivel de experiencia: ${config.nivelExperiencia}
- Área de interés: ${config.areaInteres}

REGLAS ESTRICTAS DE RESPUESTA:
1. Basa tu respuesta ÚNICAMENTE en la información de los cursos del contexto. NO inventes cursos, herramientas ni certificaciones que no figuren allí.
2. Si la información del catálogo es insuficiente para cubrir la totalidad de lo pedido, reconócelo explícitamente.
3. Explica con claridad y calidez por qué cada curso recomendado encaja con el perfil y la consulta del estudiante.
4. Destaca el nombre de cada curso y sus modalidades/niveles.
5. Sé conciso y directo: tu respuesta no debe exceder 1500 caracteres (máximo 250 palabras).

CONTEXTO DE CURSOS DISPONIBLES:
${contexto}

CONSULTA DEL ESTUDIANTE:
${config.pregunta}`;

return [{
  json: {
    consultaId: config.consultaId,
    pregunta: config.pregunta,
    prompt,
    cursos
  }
}];

