const respuestaLLM = $input.first().json;
const contexto = $('Construir Contexto RAG').first().json;

let texto = respuestaLLM.choices?.[0]?.message?.content ?? 'Te sugerimos los cursos relacionados a continuación.';
if (texto.length > 1950) {
  texto = texto.substring(0, 1947) + '...';
}

return [{
  json: {
    consultaId: contexto.consultaId,
    pregunta: contexto.pregunta,
    estado: 'Respondida',
    respuesta: texto,
    fuentes: contexto.cursos.map(c => ({
      cursoId: c.cursoId,
      similitud: c.similitud
    }))
  }
}];
